// [vite-esm] imports auto-generated by the 2026-07 Vite migration.
import "../../state.js";
import "./_helpers.js";

/* "List of classes" report template — paginated A4 portrait roster using
 * shared printTemplateUtils so Tuning, headers, and footers stay consistent.
 */
(function () {
  "use strict";
  const U = window.APP && window.APP.printTemplateUtils;
  if (!window.APP || !window.APP.printTemplates || !U) return;
  const { el, page, header, footer, emptyPage } = U;

  const PER_PAGE = 18;

  function render(school) {
    school = school || (window.APP && window.APP.school);
    const classes = (school && school.classes) ? school.classes : [];
    if (!classes.length) return [emptyPage("No classes")];

    const lessons = school.lessons || [];
    const teachers = school.teachers || [];
    const totalPages = Math.ceil(classes.length / PER_PAGE);
    const pages = [];

    for (let i = 0; i < classes.length; i += PER_PAGE) {
      const chunk = classes.slice(i, i + PER_PAGE);
      const p = page(false);
      const sub = [U.schoolTitle(school), "page " + (i / PER_PAGE + 1) + "/" + totalPages].filter(Boolean).join("  ·  ");
      p.appendChild(header("List of classes", sub));

      const tbl = el("table", { class: "tt-list", style: U.tableCSS() });
      const thead = el("thead", null,
        el("tr", null,
          el("th", { style: U.thCSS() + ";width:32px;text-align:right" }, "#"),
          el("th", { style: U.thCSS() }, "Name"),
          el("th", { style: U.thCSS() }, "Short"),
          el("th", { style: U.thCSS() }, "Class teacher"),
          el("th", { style: U.thCSS() + ";text-align:right" }, "Lessons"),
          el("th", { style: U.thCSS() + ";text-align:right" }, "Periods/week"),
        ));
      tbl.appendChild(thead);

      const tbody = el("tbody");
      chunk.forEach((c, idx) => {
        const tch = teachers.find(t => t.id === c.teacherId);
        const myLessons = lessons.filter(l => (l.classIds || []).includes(c.id));
        const totalPpw = myLessons.reduce((s, l) => s + (l.periodsPerWeek || 0), 0);
        const tr = el("tr", null,
          el("td", { style: U.tdCSS() + ";text-align:right;color:#666" }, String(i + idx + 1)),
          el("td", { style: U.tdCSS() + ";font-weight:600;color:" + (c.color || "#0f172a") }, c.name || "—"),
          el("td", { style: U.tdCSS() }, c.short || ""),
          el("td", { style: U.tdCSS() }, tch?.name || "—"),
          el("td", { style: U.tdCSS() + ";text-align:right" }, String(myLessons.length)),
          el("td", { style: U.tdCSS() + ";text-align:right" }, String(totalPpw)),
        );
        tbody.appendChild(tr);
      });
      tbl.appendChild(tbody);
      p.appendChild(tbl);
      p.appendChild(el("div", { style: "margin-top:8px;font-size:9px;color:#666" },
        "Total classes: " + classes.length));
      p.appendChild(footer());
      pages.push(p);
    }
    return pages;
  }

  window.APP.printTemplates.register("list_of_classes", {
    name: "List of classes",
    title: "List of classes",
    category: "lists",
    render,
  });
})();

// Chronexa Web
